<style>
.wt-checkout{max-width:1024px;margin:auto;padding:40px 32px}.wt-checkout-grid{display:grid;grid-template-columns:3fr 2fr;gap:40px;align-items:start}.wt-checkout-panel{background:white;border:1px solid #f3f4f6;padding:24px;margin-bottom:32px;min-width:0}.wt-checkout-fields{display:grid;grid-template-columns:1fr 1fr;gap:16px}.wt-checkout-wide{grid-column:1/-1}.wt-checkout label{display:block;margin-bottom:4px}.wt-checkout input{width:100%;min-width:0;border:1px solid #e5e7eb;padding:12px 16px;font-size:14px}.wt-checkout input:focus{outline:2px solid #4a0e17;outline-offset:2px}.wt-checkout h1,.wt-checkout h2{margin-bottom:24px}.wt-checkout-summary{position:sticky;top:24px}.wt-checkout-row{display:flex;justify-content:space-between;gap:12px;margin-bottom:20px;overflow-wrap:anywhere}.wt-checkout-row>div{min-width:0}.wt-checkout-error{color:#991b1b;margin:8px 0}.wt-checkout-submit{width:100%;padding:20px}.wt-checkout-submit:disabled{opacity:.6}.wt-checkout-header{text-align:center;padding:16px 24px;background:#4a0e17}.wt-checkout-header img{height:32px;margin:auto}.wt-checkout p{overflow-wrap:anywhere}.wt-checkout-received{max-width:640px;margin:40px auto;text-align:center}@media(max-width:1023px){.wt-checkout-grid{grid-template-columns:1fr}.wt-checkout-summary{position:static}.wt-checkout{padding:32px 16px}}@media(max-width:639px){.wt-checkout-fields{grid-template-columns:1fr}.wt-checkout-panel{padding:20px}.wt-checkout-grid{gap:16px}}
</style>
<style>
.wt-checkout-grid{grid-template-columns:minmax(0,3fr) minmax(0,2fr);gap:32px}
.wt-checkout-details{min-width:0;grid-column:1;grid-row:1}
.wt-checkout-details .wt-checkout-panel:last-child{margin-bottom:0}
.wt-checkout-summary{grid-column:2;grid-row:1 / span 2;max-height:calc(100dvh - 48px);overflow:auto}
.wt-checkout-action{grid-column:1;grid-row:2;min-width:0}
.wt-checkout-action p{font-size:13px;line-height:1.7;margin-bottom:16px;color:#666}
.wt-checkout .btn-gold,.wt-checkout .btn-outline{display:inline-flex;align-items:center;justify-content:center;min-height:48px;max-width:100%;text-align:center;white-space:normal}
.wt-checkout-panel>p{margin:12px 0;line-height:1.6}
.wt-checkout-panel h3{margin-top:20px}
.wt-checkout-row>span{flex-shrink:0}
.wt-checkout-header img{max-width:100%;height:auto;max-height:32px}
.wt-checkout-received>p{margin:16px 0;line-height:1.6}
.wt-payment-pending{display:inline-block;width:18px;height:18px;border:2px solid #eadfc8;border-top-color:#41171b;border-radius:50%;animation:wt-payment-spin 1s linear infinite;vertical-align:middle;margin-right:8px}
@keyframes wt-payment-spin{to{transform:rotate(360deg)}}
@media(prefers-reduced-motion:reduce){.wt-payment-pending{animation:none}}
@media(max-width:1023px){.wt-checkout-grid{grid-template-columns:minmax(0,1fr)}.wt-checkout-details,.wt-checkout-summary,.wt-checkout-action{grid-column:auto;grid-row:auto}.wt-checkout-summary{max-height:none;overflow:visible;margin-bottom:0}}
</style>
